// c235: the shared `page.goto` waits for hydration (tests/fixtures.ts); the
// generator's own import clicked server-rendered markup and, under the tv
// project's parallelism, landed before SvelteKit had answered.
import { expect, test } from './fixtures';

/**
 * Series on a TV, in a real browser.
 *
 * Generated by design-tools/gen-conformance.mjs from the design handoff, and
 * checked in deliberately. These assert the frame and the measurements — the
 * part visual review reliably misses. The numbers are hand-set in the mock and
 * do not round to a spacing ladder, so a later pass that tidies them would
 * silently redraw the screen. That is what this is here to stop; it is not
 * pedantry.
 *
 * Source: /home/masshiro/work/tsundoku/wave2/layout/doc/design/handoff/TV-Series.dc.html
 * Extracted at 2026-11-02T01:04:32.086Z at 1440x2400.
 *
 * Regenerating overwrites this file. Hand edits belong in a sibling spec.
 */

const base = process.env.PLAYWRIGHT_BASE_URL ?? '';

/*
 * The handoff draws one series; the seeded database has its own ids. Open one
 * by title, as series-layout does -- Boku no Kokoro no Yabai Yatsu, which no flow file
 * writes (the flows run beside this project on the shared preview's database;
 * series-flow reads Tower of God and hides Ame no Hi no Toshokan, and tv-series' RATING
 * case moves this one's rating and back, which the frame does not read).
 * This is the one hand edit to this generated file: regenerating writes the
 * plain `page.goto(base + '/')` back, and it has to be re-pointed.
 */
async function go(page: import('@playwright/test').Page) {
	await page.goto(`${base}/?sort=title`);
	await page.locator('.grid .tile', { hasText: 'Boku no Kokoro no Yabai Yatsu' }).click();
	await page.waitForURL(/\/series\/\d+/);
	await page.getByRole('heading', { name: 'Boku no Kokoro no Yabai Yatsu' }).waitFor();
}

const SEL = {
	frame: 'body',
	identity: '.panel-col .identity',
	names: '.panel-col .names',
	continue: '.panel-col .cta'
};

test('Series on a TV: frame matches the handoff', async ({ page }) => {
	await go(page);
	await expect(page.locator(SEL.frame)).toBeVisible();

	const frameStyle = await page.locator(SEL.frame).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display
		};
	});
	expect(frameStyle.display).toBe('block');
});

test('Series on a TV: identity matches the handoff', async ({ page }) => {
	await go(page);
	await expect(page.locator(SEL.identity)).toBeVisible();

	const identityStyle = await page.locator(SEL.identity).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display,
			rowGap: cs.rowGap,
			columnGap: cs.columnGap
		};
	});
	expect(identityStyle.display).toBe('flex');
	expect(identityStyle.rowGap).toBe('16px');
	expect(identityStyle.columnGap).toBe('16px');
});

test('Series on a TV: names matches the handoff', async ({ page }) => {
	await go(page);
	await expect(page.locator(SEL.names)).toBeVisible();

	const namesStyle = await page.locator(SEL.names).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display,
			flexDirection: cs.flexDirection,
			rowGap: cs.rowGap,
			columnGap: cs.columnGap
		};
	});
	expect(namesStyle.display).toBe('flex');
	expect(namesStyle.flexDirection).toBe('column');
	expect(namesStyle.rowGap).toBe('8px');
	expect(namesStyle.columnGap).toBe('8px');
});

test('Series on a TV: continue matches the handoff', async ({ page }) => {
	await go(page);
	await expect(page.locator(SEL.continue)).toBeVisible();

	const continueStyle = await page.locator(SEL.continue).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display,
			alignItems: cs.alignItems,
			rowGap: cs.rowGap,
			columnGap: cs.columnGap,
			paddingTop: cs.paddingTop,
			paddingRight: cs.paddingRight,
			paddingBottom: cs.paddingBottom,
			paddingLeft: cs.paddingLeft,
			fontSize: cs.fontSize,
			fontWeight: cs.fontWeight,
			letterSpacing: cs.letterSpacing,
			lineHeight: cs.lineHeight
		};
	});
	expect(continueStyle.display).toBe('flex');
	expect(continueStyle.alignItems).toBe('center');
	expect(continueStyle.rowGap).toBe('14px');
	expect(continueStyle.columnGap).toBe('14px');
	expect(continueStyle.paddingTop).toBe('0px');
	expect(continueStyle.paddingRight).toBe('20px');
	expect(continueStyle.paddingBottom).toBe('0px');
	expect(continueStyle.paddingLeft).toBe('20px');
	expect(continueStyle.fontSize).toBe('17px');
	expect(continueStyle.fontWeight).toBe('500');
	expect(continueStyle.letterSpacing).toBe('0.34px'); // authored 0.02em
	expect(continueStyle.lineHeight).toBe('20.4px');
});
